package com.mockingjam.spirecraft.worldgen;

import com.mockingjam.spirecraft.SpireCraft;
import java.util.List;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.tags.TagKey;
import net.minecraft.world.level.biome.Biome;

/**
 * The twelve biomes of docs/design/biomes_v2.md (JSON generated by datagen/BiomeData; placed into the overworld —
 * surface slices and underground cave slices — by WorldPresetProvider).
 */
public final class ModBiomes {
    // dark harbours and the polluted sea
    public static final ResourceKey<Biome> STONE_FOREST_DOCKS = key("stone_forest_docks");
    public static final ResourceKey<Biome> BEACH_DOCKS = key("beach_docks");
    public static final ResourceKey<Biome> POLLUTED_SEA = key("polluted_sea");
    public static final ResourceKey<Biome> WATERFALLS = key("waterfalls");
    // the overgrowth family
    public static final ResourceKey<Biome> OVERGROWTH = key("overgrowth");
    public static final ResourceKey<Biome> MISTY_OVERGROWTH = key("misty_overgrowth");
    public static final ResourceKey<Biome> MUSHROOM_OVERGROWTH = key("mushroom_overgrowth");
    // caves
    public static final ResourceKey<Biome> INK_SPRING_CAVES = key("ink_spring_caves");
    public static final ResourceKey<Biome> HIVE_CAVES = key("hive_caves");
    public static final ResourceKey<Biome> SPARSE_HIVE_CAVES = key("sparse_hive_caves");
    public static final ResourceKey<Biome> EGG_HIVE_CAVES = key("egg_hive_caves");
    public static final ResourceKey<Biome> QUICKSAND_CAVES = key("quicksand_caves");

    public static final List<ResourceKey<Biome>> ALL = List.of(STONE_FOREST_DOCKS, BEACH_DOCKS, POLLUTED_SEA, WATERFALLS,
            OVERGROWTH, MISTY_OVERGROWTH, MUSHROOM_OVERGROWTH, INK_SPRING_CAVES, HIVE_CAVES, SPARSE_HIVE_CAVES, EGG_HIVE_CAVES);
    /** v3.2: no longer placed in the world (quicksand is on the desert surface now); kept registered for old worlds. */
    public static final List<ResourceKey<Biome>> CAVES = List.of(INK_SPRING_CAVES, HIVE_CAVES, SPARSE_HIVE_CAVES, EGG_HIVE_CAVES);
    public static final List<ResourceKey<Biome>> OVERGROWTHS = List.of(OVERGROWTH, MISTY_OVERGROWTH, MUSHROOM_OVERGROWTH);

    /** Biomes whose water is polluted (wading in it gives Weakness). */
    public static final TagKey<Biome> POLLUTED_WATER = TagKey.create(Registries.BIOME, SpireCraft.id("polluted_water"));

    private ModBiomes() {}

    private static ResourceKey<Biome> key(String name) {
        return ResourceKey.create(Registries.BIOME, SpireCraft.id(name));
    }
}
